DROP TABLE IF EXISTS `lecturers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lecturers` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nidn` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `homebase` enum('jtik','external') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `profile_status` enum('unverified','verified') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'unverified',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `source_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `nip` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_data` json DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `lecturers_nidn_unique` (`nidn`),
  UNIQUE KEY `lecturers_nip_unique` (`nip`)
) ENGINE=InnoDB AUTO_INCREMENT=137 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
