--
-- Table structure for table `schedule_sessions`
--

DROP TABLE IF EXISTS `schedule_sessions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `schedule_sessions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `schedule_version_id` bigint unsigned NOT NULL,
  `course_offering_id` bigint unsigned DEFAULT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `mode` enum('offline','online','unscheduled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'offline',
  `day_of_week` tinyint unsigned DEFAULT NULL,
  `start_minute` smallint unsigned DEFAULT NULL,
  `end_minute` smallint unsigned DEFAULT NULL,
  `room_id` bigint unsigned DEFAULT NULL,
  `phase` enum('full','before_uts','after_uts') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'full',
  `source_file` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
